// 设备报警值解析
// 0=正常, 1=气路, 2=水路, 3-6=漏水, 7=PLC通讯, 8=模块通讯
var alarmValue = getTag('Device_Alarm');
var alarmMessages = {
  0: '正常',
  1: '气路报警',
  2: '水路报警',
  3: '1#区漏水',
  4: '2#区漏水',
  5: '3#区漏水',
  6: '4#区漏水',
  7: '屏幕PLC通讯异常',
  8: '采集模块通讯异常'
};

var message = alarmMessages[alarmValue] || '未知报警';
setTag('Device_Alarm_Message', message);

// 统计运行中的区域数量
var count = 0;
if (getTag('Zone1_Status') === 1) count++;
if (getTag('Zone2_Status') === 1) count++;
if (getTag('Zone3_Status') === 1) count++;
if (getTag('Zone4_Status') === 1) count++;

setTag('Total_Zone_Running', count);

// 湿度限值验证：高限必须大于低限
function validateLimit(highTag, lowTag) {
  var high = getTag(highTag);
  var low = getTag(lowTag);

  if (high <= low) {
    return { success: false, message: '高限必须大于低限' };
  }
  if (high > 99 || low > 99) {
    return { success: false, message: '限值不能超过99%' };
  }
  return { success: true };
}

// 各区域验证
var results = [];
results.push(validateLimit('Zone1_HighLimit', 'Zone1_LowLimit'));
results.push(validateLimit('Zone2_HighLimit', 'Zone2_LowLimit'));
results.push(validateLimit('Zone3_HighLimit', 'Zone3_LowLimit'));
results.push(validateLimit('Zone4_HighLimit', 'Zone4_LowLimit'));

var allValid = results.every(function(r) { return r.success; });
if (!allValid) {
  var errorMsg = results.find(function(r) { return !r.success; }).message;
  return { success: false, message: errorMsg };
}

return { success: true, message: '参数验证通过' };

// 设备通讯状态监测
// 当任意标签值变化时检查通讯状态
var zone1Status = getTag('Zone1_Status');

if (zone1Status === null || zone1Status === undefined) {
  // 通讯异常
  setTag('Connection_Status', 'offline');
  setTag('Last_Communication_Time', new Date().toISOString());
} else {
  // 通讯正常
  setTag('Connection_Status', 'online');
  setTag('Last_Communication_Time', new Date().toISOString());
}

