// 每小时统计数据记录
var report = {
  timestamp: new Date().toISOString(),
  zone1: { humidity: getTag('Zone1_Humidity_Display'), temp: getTag('Zone1_Temp_Display') },
  zone2: { humidity: getTag('Zone2_Humidity_Display'), temp: getTag('Zone2_Temp_Display') },
  zone3: { humidity: getTag('Zone3_Humidity_Display'), temp: getTag('Zone3_Temp_Display') },
  zone4: { humidity: getTag('Zone4_Humidity_Display'), temp: getTag('Zone4_Temp_Display') }
};

console.log('每小时报告:', JSON.stringify(report));

// 每日统计计算
// 注意：实际实现需要历史数据支持
var now = new Date();
var dateStr = now.toISOString().split('T')[0];

var dailyReport = {
  date: dateStr,
  zones: []
};

// 各区域统计
for (var i = 1; i <= 4; i++) {
  var zone = {
    zone: i + '#区',
    avgHumidity: 0,
    avgTemp: 0,
    runningHours: 0,
    alarmCount: 0
  };
  dailyReport.zones.push(zone);
}

console.log('每日统计:', JSON.stringify(dailyReport));
return dailyReport;

// 湿度达标率检查
// 检查各区域当前湿度是否在设定的高/低限范围内

var zones = [1, 2, 3, 4];
var complianceResults = [];

zones.forEach(function(zoneNum) {
  var highLimit = getTag('Zone' + zoneNum + '_HighLimit');
  var lowLimit = getTag('Zone' + zoneNum + '_LowLimit');
  var currentHumidity = getTag('Zone' + zoneNum + '_Humidity_Display');

  if (currentHumidity !== null && highLimit !== null && lowLimit !== null) {
    var isCompliant = currentHumidity >= lowLimit && currentHumidity <= highLimit;
    complianceResults.push({
      zone: zoneNum + '#区',
      humidity: currentHumidity,
      range: lowLimit + '% - ' + highLimit + '%',
      compliant: isCompliant
    });
  }
});

console.log('达标率检查:', JSON.stringify(complianceResults));

// 运行时间累计统计
// 每小时检查各区域运行状态并累计时间

var zones = [1, 2, 3, 4];
var runningData = {};

zones.forEach(function(zoneNum) {
  var status = getTag('Zone' + zoneNum + '_Status');
  var runningKey = 'Zone' + zoneNum + '_RunningHours';
  var currentHours = getTag(runningKey) || 0;

  // 如果正在运行，加1小时
  if (status === 1) {
    setTag(runningKey, currentHours + 1);
    runningData['Zone' + zoneNum] = currentHours + 1;
  } else {
    runningData['Zone' + zoneNum] = currentHours;
  }
});

console.log('运行时间累计:', JSON.stringify(runningData));
return runningData;
